    from models import User
    try:
        return User.query.get(int(user_id))
    except (ValueError, Exception) as e:
        logger.error(f"Error loading user {user_id}: {e}")
        return None

def init_database_with_retry(max_attempts=15, base_delay=1):
    for attempt in range(1, max_attempts + 1):
        try:
            logger.info(f"Database initialization attempt {attempt}/{max_attempts}")

            with app.app_context():
                with db.engine.begin() as conn:
                    conn.execute(db.text("SELECT 1"))

                import models
                db.create_all()

            logger.info("Database initialized successfully")
            return True

        except OperationalError as e:
            error_lower = str(e).lower()
            if "endpoint has been disabled" in error_lower or "connection" in error_lower or "timeout" in error_lower:
                delay = base_delay * (2 ** (attempt - 1))
                if attempt < max_attempts:
                    logger.warning(
                        f"Database connection failed (attempt {attempt}/{max_attempts}): {str(e)[:100]}. "
                        f"Retrying in {delay} seconds..."
                    )
                    time.sleep(delay)
                else:
                    logger.critical(
                        f"Database initialization failed after {max_attempts} attempts"
                    )
                    return False
            else:
                logger.error(f"Unrecoverable database error: {e}")
                raise
        except Exception as e:
            logger.error(f"Unexpected database initialization error: {e}")
            raise

with app.app_context():
    if not init_database_with_retry():
        logger.critical("Failed to initialize database - application cannot start")
        sys.exit(1)

