logger = logging.getLogger(__name__)

class CoinbaseCommerceAPI:
    BASE_URL = ""
    API_VERSION = "2018-03-22"
    REQUEST_TIMEOUT = 30
    MAX_RETRIES = 3

    def __init__(self):
        self.api_key = os.environ.get("COINBASE_API_KEY")
        self.api_secret = os.environ.get("COINBASE_API_SECRET")

        if not self.api_key:
            raise ValueError("COINBASE_API_KEY environment variable is required")

        if not self.api_secret:
            raise ValueError("COINBASE_API_SECRET environment variable is required")

        self.session = requests.Session()
        self.session.headers.update(self._get_headers())

    def _get_headers(self) -> Dict[str, str]:
        return {
            "X-CC-Api-Key": self.api_key,
            "X-CC-Version": self.API_VERSION,
            "Content-Type": "application/json",
            "User-Agent": "TiffyTime/1.0"
        }

    def _make_request(self, method: str, endpoint: str, data: Optional[Dict] = None, params: Optional[Dict] = None) -> Dict[str, Any]:
        url = f"{self.BASE_URL}/{endpoint}"

        for attempt in range(self.MAX_RETRIES):
            try:
                if method == "GET":
                    response = self.session.get(url, params=params, timeout=self.REQUEST_TIMEOUT)
                elif method == "POST":
                    response = self.session.post(url, json=data, params=params, timeout=self.REQUEST_TIMEOUT)
                else:
                    raise ValueError(f"Unsupported HTTP method: {method}")

                response.raise_for_status()
                return response.json()

            except requests.exceptions.Timeout:
                if attempt < self.MAX_RETRIES - 1:
                    logger.warning(f"Request timeout, retrying {attempt + 1}/{self.MAX_RETRIES}")
                    continue
                raise
            except requests.exceptions.ConnectionError as e:
                if attempt < self.MAX_RETRIES - 1:
                    logger.warning(f"Connection error, retrying {attempt + 1}/{self.MAX_RETRIES}")
                    continue
                raise
            except requests.exceptions.HTTPError as e:
                logger.error(f"HTTP Error: {e.response.status_code} - {e.response.text}")
                raise
            except requests.exceptions.RequestException as e:
                logger.error(f"Request failed: {e}")
                raise

    def create_charge(self, amount_huf: float, description: str, metadata: Optional[Dict] = None) -> Dict[str, Any]:
        if not isinstance(amount_huf, (int, float)) or amount_huf <= 0:
            raise ValueError("Amount must be a positive number")

        if not description or not isinstance(description, str) or len(description.strip()) == 0:
            raise ValueError("Description is required")

        try:
            amount_usd = round(amount_huf / 380.0, 2)

            if amount_usd < 0.01:
                raise ValueError("Amount is too small (minimum USD 0.01)")

            charge_data = {
                "name": f"Fizetés - {amount_huf:,.0f} HUF",
                "description": f"{description}\n\nÖsszeg: {amount_huf:,.0f} HUF",
                "pricing_type": "fixed_price",
                "local_price": {
                    "amount": str(amount_usd),
                    "currency": "USD"
                },
                "metadata": {
                    "amount_huf": str(amount_huf),
                    "original_currency": "HUF",
                    "created_at": datetime.utcnow().isoformat()
                }
            }

            if metadata and isinstance(metadata, dict):
                charge_data["metadata"].update(metadata)

            logger.info(f"Creating Coinbase charge: {amount_huf} HUF (${amount_usd} USD)")

            response = self._make_request("POST", "charges", data=charge_data)

            if "data" in response:
                charge = response["data"]
                logger.info(f"Coinbase charge created: {charge.get('id')}")
                return charge
            else:
                raise Exception("Invalid response format from Coinbase")

        except Exception as e:
            logger.error(f"Coinbase charge creation failed: {e}")
            raise

    def get_charge(self, charge_id: str) -> Optional[Dict[str, Any]]:
        if not charge_id or not isinstance(charge_id, str):
            raise ValueError("Charge ID is required")

        try:
            response = self._make_request("GET", f"charges/{charge_id}")

            if "data" in response:
                return response["data"]

            logger.warning(f"No data in response for charge {charge_id}")
            return None

        except Exception as e:
            logger.error(f"Failed to get charge {charge_id}: {e}")
            return None

    def verify_webhook_signature(self, payload: bytes, signature: str) -> bool:
        if not self.api_secret or not signature:
            logger.error("API secret or signature missing")
            return False

        try:
            expected_signature = hmac.new(
                self.api_secret.encode('utf-8'),
                payload,
                hashlib.sha256
            ).hexdigest()

            return hmac.compare_digest(expected_signature, signature)

        except Exception as e:
            logger.error(f"Webhook signature verification failed: {e}")
            return False

    def parse_webhook_event(self, payload: Dict[str, Any]) -> Optional[Dict[str, Any]]:
        try:
            event_data = payload.get("event", {})
            event_type = event_data.get("type", "").lower()
            charge_data = event_data.get("data", {})

            timeline = charge_data.get("timeline", [])
            status = timeline[-1].get("status", "UNKNOWN") if timeline else "UNKNOWN"

            return {
                "event_type": event_type,
                "charge_id": charge_data.get("id"),
                "status": status.upper(),
                "amount_huf": charge_data.get("metadata", {}).get("amount_huf"),
                "payments": charge_data.get("payments", []),
                "created_at": charge_data.get("created_at"),
                "expires_at": charge_data.get("expires_at"),
                "address": charge_data.get("address", {}),
                "received": charge_data.get("received", {})
            }

        except Exception as e:
            logger.error(f"Failed to parse webhook event: {e}")
            return None
