import requests
import json
import logging
import uuid
from datetime import datetime, timedelta
from typing import Dict, Optional, Any, List
from urllib.parse import urlencode
from config import config

logger = logging.getLogger(__name__)

class ErsteAPIClient:
    REQUEST_TIMEOUT = 30
    MAX_RETRIES = 3

    def __init__(self):
        self.base_url = config.erste_api_url
        self.web_api_key = config.ERSTE_WEB_API_KEY
        self.client_id = config.ERSTE_CLIENT_ID
        self.client_secret = config.ERSTE_CLIENT_SECRET
        self.redirect_uri = config.ERSTE_REDIRECT_URI
        self.session = requests.Session()

    def _get_headers(self, access_token: Optional[str] = None, additional_headers: Optional[Dict] = None) -> Dict[str, str]:
        headers = {
            'Content-Type': 'application/json',
            'web-api-key': self.web_api_key,
            'X-Request-ID': str(uuid.uuid4()),
            'User-Agent': 'TiffyTime/1.0'
        }

        if access_token:
            headers['Authorization'] = f'Bearer {access_token}'

        if additional_headers:
            headers.update(additional_headers)

        return headers

    def _make_request(self, method: str, endpoint: str, access_token: Optional[str] = None, 
                     data: Optional[Dict] = None, params: Optional[Dict] = None) -> Dict[str, Any]:
        url = f"{self.base_url}{endpoint}"
        headers = self._get_headers(access_token)

        for attempt in range(self.MAX_RETRIES):
            try:
                if method == "GET":
                    response = self.session.get(url, headers=headers, params=params, timeout=self.REQUEST_TIMEOUT)
                elif method == "POST":
                    response = self.session.post(url, headers=headers, json=data, params=params, timeout=self.REQUEST_TIMEOUT)
                else:
                    raise ValueError(f"Unsupported HTTP method: {method}")

                response.raise_for_status()
                return response.json()

            except requests.exceptions.Timeout:
                if attempt < self.MAX_RETRIES - 1:
                    logger.warning(f"Request timeout for {endpoint}, retrying {attempt + 1}/{self.MAX_RETRIES}")
                    continue
                raise
            except requests.exceptions.HTTPError as e:
                logger.error(f"HTTP Error {e.response.status_code} for {endpoint}: {e.response.text}")
                raise
            except Exception as e:
                logger.error(f"Request failed for {endpoint}: {e}")
                raise

    def create_consent(self, access_types: List[str] = None) -> Dict[str, Any]:
        if access_types is None:
            access_types = ['accounts', 'balances', 'transactions']

        payload = {
            "access": {
                "accounts": [],
                "balances": [],
                "transactions": []
            },
            "recurringIndicator": True,
            "validUntil": (datetime.utcnow() + timedelta(days=90)).strftime("%Y-%m-%d"),
            "frequencyPerDay": 10,
            "combinedServiceIndicator": False
        }

        try:
            logger.info("Creating PSD2 consent")
            response = self._make_request("POST", "/consents", data=payload)
            return response
        except Exception as e:
            logger.error(f"Error creating consent: {e}")
            raise

    def get_authorization_url(self, consent_id: str) -> str:
        if not consent_id:
            raise ValueError("Consent ID is required")

        params = {
            'response_type': 'code',
            'client_id': self.client_id,
            'redirect_uri': self.redirect_uri,
            'scope': 'aisp pisp',
            'state': consent_id,
            'consentId': consent_id
        }

        auth_url = f"{self.base_url}/auth?" + urlencode(params)
        return auth_url

    def exchange_code_for_token(self, authorization_code: str, consent_id: str) -> Dict[str, Any]:
        if not authorization_code or not consent_id:
            raise ValueError("Authorization code and consent ID are required")

        payload = {
            'grant_type': 'authorization_code',
            'client_id': self.client_id,
            'client_secret': self.client_secret,
            'code': authorization_code,
            'redirect_uri': self.redirect_uri
        }

        headers = {
            'Content-Type': 'application/x-www-form-urlencoded',
            'web-api-key': self.web_api_key
        }

        try:
            logger.info("Exchanging authorization code for token")
            response = self.session.post(f"{self.base_url}/token", data=payload, headers=headers, timeout=self.REQUEST_TIMEOUT)
            response.raise_for_status()
            return response.json()
        except Exception as e:
            logger.error(f"Error exchanging code for token: {e}")
            raise

    def get_accounts(self, access_token: str) -> Dict[str, Any]:
        if not access_token:
            raise ValueError("Access token is required")

        try:
            logger.info("Retrieving accounts")
            response = self._make_request("GET", "/accounts", access_token=access_token)
            return response
        except Exception as e:
            logger.error(f"Error retrieving accounts: {e}")
            raise

    def get_account_balances(self, access_token: str, account_id: str) -> Dict[str, Any]:
        if not access_token or not account_id:
            raise ValueError("Access token and account ID are required")

        try:
            logger.info(f"Retrieving balances for account {account_id}")
            response = self._make_request("GET", f"/accounts/{account_id}/balances", access_token=access_token)
            return response
        except Exception as e:
            logger.error(f"Error retrieving account balances: {e}")
            raise

    def get_transactions(self, access_token: str, account_id: str, date_from: Optional[str] = None, 
                        date_to: Optional[str] = None) -> Dict[str, Any]:
        if not access_token or not account_id:
            raise ValueError("Access token and account ID are required")

        params = {}
        if date_from:
            params['dateFrom'] = date_from
        if date_to:
            params['dateTo'] = date_to

        try:
            logger.info(f"Retrieving transactions for account {account_id}")
            response = self._make_request("GET", f"/accounts/{account_id}/transactions", 
                                        access_token=access_token, params=params)
            return response
        except Exception as e:
            logger.error(f"Error retrieving transactions: {e}")
            raise

    def initiate_payment(self, access_token: str, payment_data: Dict[str, Any]) -> Dict[str, Any]:
        if not access_token or not payment_data:
            raise ValueError("Access token and payment data are required")

        required_fields = ['amount', 'debtor_iban', 'creditor_iban', 'creditor_name']
        for field in required_fields:
            if field not in payment_data:
                raise ValueError(f"Missing required field: {field}")

        try:
            amount = float(payment_data['amount'])
            if amount <= 0:
                raise ValueError("Amount must be positive")
        except (ValueError, TypeError) as e:
            raise ValueError(f"Invalid amount: {e}")

        payload = {
            "instructedAmount": {
                "currency": payment_data.get('currency', 'HUF'),
                "amount": f"{amount:.2f}"
            },
            "debtorAccount": {
                "iban": payment_data['debtor_iban']
            },
            "creditorAccount": {
                "iban": payment_data['creditor_iban']
            },
            "creditorName": payment_data['creditor_name'],
            "remittanceInformationUnstructured": payment_data.get('description', '')
        }

        try:
            logger.info(f"Initiating payment of {amount} {payload['instructedAmount']['currency']}")
            response = self._make_request("POST", "/payments/sepa-credit-transfers", 
                                        access_token=access_token, data=payload)
            return response
        except Exception as e:
            logger.error(f"Error initiating payment: {e}")
            raise

    def get_payment_status(self, access_token: str, payment_id: str) -> Dict[str, Any]:
        if not access_token or not payment_id:
            raise ValueError("Access token and payment ID are required")

        try:
            logger.info(f"Retrieving payment status for {payment_id}")
            response = self._make_request("GET", f"/payments/sepa-credit-transfers/{payment_id}", 
                                        access_token=access_token)
            return response
        except Exception as e:
            logger.error(f"Error retrieving payment status: {e}")
            raise

    def confirm_funds(self, access_token: str, account_iban: str, amount: float, currency: str = 'HUF') -> Dict[str, Any]:
        if not access_token or not account_iban:
            raise ValueError("Access token and account IBAN are required")

        try:
            amount_float = float(amount)
            if amount_float <= 0:
                raise ValueError("Amount must be positive")
        except (ValueError, TypeError) as e:
            raise ValueError(f"Invalid amount: {e}")

        payload = {
            "account": {
                "iban": account_iban
            },
            "instructedAmount": {
                "currency": currency,
                "amount": f"{amount_float:.2f}"
            }
        }

        try:
            logger.info(f"Confirming funds availability for {amount_float} {currency}")
            response = self._make_request("POST", "/funds-confirmations", 
                                        access_token=access_token, data=payload)
            return response
        except Exception as e:
            logger.error(f"Error confirming funds: {e}")
            raise

    def refresh_access_token(self, refresh_token: str) -> Dict[str, Any]:
        if not refresh_token:
            raise ValueError("Refresh token is required")

        payload = {
            'grant_type': 'refresh_token',
            'refresh_token': refresh_token,
            'client_id': self.client_id,
            'client_secret': self.client_secret
        }

        headers = {
            'Content-Type': 'application/x-www-form-urlencoded',
            'web-api-key': self.web_api_key
        }

        try:
            logger.info("Refreshing access token")
            response = self.session.post(f"{self.base_url}/token", data=payload, headers=headers, 
                                        timeout=self.REQUEST_TIMEOUT)
            response.raise_for_status()
            return response.json()
        except Exception as e:
            logger.error(f"Error refreshing access token: {e}")
            raise
