from datetime import datetime
from app import db
from flask_login import UserMixin
from werkzeug.security import generate_password_hash, check_password_hash
import uuid
from decimal import Decimal

class User(UserMixin, db.Model):
    __tablename__ = 'user'

    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(64), unique=True, nullable=False, index=True)
    email = db.Column(db.String(120), unique=True, nullable=False, index=True)
    password_hash = db.Column(db.String(512), nullable=False)
    created_at = db.Column(db.DateTime, default=datetime.utcnow, nullable=False)
    updated_at = db.Column(db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)
    erste_customer_id = db.Column(db.String(128), unique=True, nullable=True, index=True)
    consent_id = db.Column(db.String(128), unique=True, nullable=True)
    access_token = db.Column(db.Text, nullable=True)
    refresh_token = db.Column(db.Text, nullable=True)
    token_expires_at = db.Column(db.DateTime, nullable=True)

    payments = db.relationship('Payment', backref='user', lazy='select', cascade='all, delete-orphan')
    payment_links = db.relationship('PaymentLink', backref='user', lazy='select', cascade='all, delete-orphan')
    accounts = db.relationship('Account', backref='user', lazy='select', cascade='all, delete-orphan')
    transactions = db.relationship('Transaction', backref='user', lazy='select', cascade='all, delete-orphan')

    def set_password(self, password: str) -> None:
        if not password or len(password) < 8:
            raise ValueError("Password must be at least 8 characters long")
        self.password_hash = generate_password_hash(password, method='pbkdf2:sha256', salt_length=16)

    def check_password(self, password: str) -> bool:
        if not password or not self.password_hash:
            return False
        return check_password_hash(self.password_hash, password)

    def __repr__(self) -> str:
        return f'<User {self.username}>'


class Payment(db.Model):
    __tablename__ = 'payment'

    id = db.Column(db.Integer, primary_key=True)
    payment_id = db.Column(db.String(128), unique=True, nullable=False, index=True, default=lambda: str(uuid.uuid4()))
    user_id = db.Column(db.Integer, db.ForeignKey('user.id'), nullable=False, index=True)
    amount = db.Column(db.Numeric(15, 2), nullable=False)
    currency = db.Column(db.String(3), default='HUF', nullable=False)
    status = db.Column(db.String(20), default='pending', nullable=False, index=True)
    payment_method = db.Column(db.String(20), nullable=False, index=True)
    recipient_name = db.Column(db.String(256), nullable=True)
    recipient_iban = db.Column(db.String(34), nullable=True)
    description = db.Column(db.Text, nullable=True)
    created_at = db.Column(db.DateTime, default=datetime.utcnow, nullable=False, index=True)
    executed_at = db.Column(db.DateTime, nullable=True)
    erste_payment_id = db.Column(db.String(128), unique=True, nullable=True, index=True)
