    def validate_payment_data(self, data: Dict[str, Any]) -> Dict[str, Any]:
        required_fields = ['amount', 'currency', 'payment_method']
        for field in required_fields:
            if field not in data:
                raise ValueError(f"Missing required field: {field}")

        try:
            amount = Decimal(str(data['amount']))
        except Exception as e:
            raise ValueError(f"Invalid amount format: {e}")

        if amount <= 0:
            raise ValueError("Amount must be positive")

        if amount > Decimal('99999999.99'):
            raise ValueError("Amount exceeds maximum limit")

        if data['currency'] not in ['HUF', 'EUR', 'USD']:
            raise ValueError("Invalid currency")

        if data['payment_method'] not in self.VALID_PAYMENT_METHODS:
            raise ValueError(f"Invalid payment method: {data['payment_method']}")

        return {
            'amount': amount,
            'currency': data['currency'],
            'payment_method': data['payment_method']
        }

    def process_erste_payment(self, user_id: int, payment_data: Dict[str, Any]) -> Dict[str, Any]:
        idempotency_key = str(uuid.uuid4())

        try:
            user = User.query.get(user_id)
            if not user or not user.access_token:
                raise ValueError("User not authenticated with Erste Bank")

            validated_data = self.validate_payment_data(payment_data)

            required_fields = ['recipient_name', 'recipient_iban', 'debtor_iban']
            for field in required_fields:
                if field not in payment_data:
                    raise ValueError(f"Missing required field: {field}")

            payment = Payment(
                user_id=user_id,
                amount=validated_data['amount'],
                currency=validated_data['currency'],
                payment_method='erste',
                recipient_name=payment_data.get('recipient_name', '')[:256],
                recipient_iban=payment_data.get('recipient_iban', '')[:34],
                description=payment_data.get('description', '')[:500],
                status='pending',
                idempotency_key=idempotency_key,
                metadata={'initiated_at': datetime.utcnow().isoformat()}
            )

            db.session.add(payment)
            db.session.flush()

            erste_payment_data = {
                'amount': float(validated_data['amount']),
                'currency': validated_data['currency'],
                'debtor_iban': payment_data['debtor_iban'],
                'creditor_iban': payment_data['recipient_iban'],
                'creditor_name': payment_data['recipient_name'],
                'description': payment_data.get('description', '')
            }

            result = self.erste_client.initiate_payment(user.access_token, erste_payment_data)

            payment.erste_payment_id = result.get('paymentId')
            payment.status = 'initiated'
            db.session.commit()

            logger.info(f"Erste payment {payment.payment_id} initiated successfully")
            return {
                'success': True,
                'payment_id': payment.payment_id,
                'erste_payment_id': payment.erste_payment_id,
                'status': payment.status,
                'idempotency_key': idempotency_key
            }

        except Exception as e:
