    def check_payment_status(self, payment_id: str) -> Dict[str, Any]:
        try:
            payment = Payment.query.filter_by(payment_id=payment_id).first()
            if not payment:
                return {'success': False, 'error': 'Payment not found'}

            if payment.payment_method == 'erste' and payment.erste_payment_id:
                user = User.query.get(payment.user_id)
                if user and user.access_token:
                    try:
                        result = self.erste_client.get_payment_status(user.access_token, payment.erste_payment_id)

                        api_status = result.get('transactionStatus', '').upper()
                        if api_status == 'ACCC':
                            payment.status = 'completed'
                            payment.executed_at = datetime.utcnow()
                        elif api_status == 'RJCT':
                            payment.status = 'failed'
                        elif api_status in ['ACCP', 'ACSC']:
                            payment.status = 'processing'

                        db.session.commit()

                    except Exception as e:
                        logger.error(f"Error checking Erste payment status: {e}")

            return {
                'success': True,
                'payment_id': payment.payment_id,
                'status': payment.status,
                'amount': float(payment.amount),
                'currency': payment.currency,
                'created_at': payment.created_at.isoformat(),
                'executed_at': payment.executed_at.isoformat() if payment.executed_at else None
            }

        except Exception as e:
            logger.error(f"Error checking payment status: {e}")
            return {'success': False, 'error': str(e)}

    def get_user_payments(self, user_id: int, limit: int = 50, offset: int = 0) -> Dict[str, Any]:
        try:
            if limit < 1 or limit > 500:
                limit = 50
            if offset < 0:
                offset = 0

            payments = Payment.query.filter_by(user_id=user_id).order_by(
                Payment.created_at.desc()
            ).limit(limit).offset(offset).all()

            payment_list = []
            for payment in payments:
                payment_list.append({
                    'payment_id': payment.payment_id,
                    'amount': float(payment.amount),
                    'currency': payment.currency,
                    'status': payment.status,
                    'payment_method': payment.payment_method,
                    'recipient_name': payment.recipient_name,
                    'description': payment.description,
                    'created_at': payment.created_at.isoformat(),
                    'executed_at': payment.executed_at.isoformat() if payment.executed_at else None
                })

            total = Payment.query.filter_by(user_id=user_id).count()

            return {
                'success': True,
                'payments': payment_list,
                'total': total,
                'limit': limit,
                'offset': offset
            }

        except Exception as e:
            logger.error(f"Error retrieving user payments: {e}")
            return {'success': False, 'error': str(e)}

    def handle_coinbase_webhook(self, event_data: Dict[str, Any]) -> Dict[str, Any]:
        try:
            parsed_event = self.coinbase_client.parse_webhook_event(event_data)
            if not parsed_event:
                return {'success': False, 'error': 'Invalid webhook data'}

            charge_id = parsed_event.get('charge_id')
            event_type = parsed_event.get('event_type', '').lower()
            status = parsed_event.get('status', '').upper()

            payment = Payment.query.filter_by(transaction_id=charge_id).first()
            if not payment:
                logger.warning(f"Payment not found for Coinbase charge {charge_id}")
                return {'success': False, 'error': 'Payment not found'}

            if event_type == 'charge:confirmed' or status == 'COMPLETED':
                payment.status = 'completed'
                payment.executed_at = datetime.utcnow()
            elif event_type == 'charge:failed' or status == 'EXPIRED':
                payment.status = 'failed'
            elif status == 'PENDING':
                payment.status = 'processing'

            payment.metadata = payment.metadata or {}
            payment.metadata['last_webhook_event'] = event_type
            payment.metadata['last_webhook_status'] = status
            payment.metadata['last_webhook_time'] = datetime.utcnow().isoformat()

            db.session.commit()

            logger.info(f"Updated payment {payment.payment_id} from webhook: {status}")
            return {'success': True, 'payment_id': payment.payment_id, 'status': payment.status}

        except Exception as e:
